'use client';

import { useEffect, useState } from 'react';
import './Home.css';

export default function Home() {
  const [logoVisible, setLogoVisible] = useState(false);

  useEffect(() => {
    const timer = window.setTimeout(() => {
      setLogoVisible(true);
    }, 1350);

    return () => window.clearTimeout(timer);
  }, []);

  return (
    <div id="Home" className="tabcontent">
      <div className="header-container">
        <div className="typing-text-container">
          <h1 className="typing-text">Welcome to...</h1>
        </div>

        {logoVisible && (
          <div className="logo-container">
            <img
              src="/img/nocturne-lettering.svg"
              alt="Nocturne"
              className="logo"
            />
          </div>
        )}
      </div>

      <div className="link-container">
        <a
          href="https://ra.co/events/2243135"
          className="link-button"
          target="_blank"
          rel="noopener noreferrer"
        >
          Electropolis | Halloween Edition
          <br />
          31 October - Tickets
        </a>

        <a
          href="https://nocturnemlb.secure-decoration.com"
          className="link-button"
          target="_blank"
          rel="noopener noreferrer"
        >
          🦇 Merch 🦇
        </a>

        <a href="/mailing-list" className="link-button">
          Join The Nocturne Family 🦇
          <br />
          Sign Up to Our Mailing List
        </a>
      </div>
    </div>
  );
}